INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7664690, 1250323, 39144, '<td valign="top">I really like the contrast between the black background and the white dandelion.</td>', 'I really like the contrast between the black background and the white dandelion.', '2020-06-01 01:06:46.000000', NULL, 1),
(7664692, 1250242, 39144, '<td valign="top">Its crazy how empty that place is.</td>', 'Its crazy how empty that place is.', '2020-06-01 01:08:20.000000', NULL, 1),
(7664693, 1250119, 39144, '<td valign="top">It amazes me how much detail you have captures in this image. Great work.</td>', 'It amazes me how much detail you have captures in this image. Great work.', '2020-06-01 01:12:20.000000', NULL, 1),
(7664745, 1250246, 113411, '<td valign="top">What a beautiful animal!</td>', 'What a beautiful animal!', '2020-06-01 10:30:20.000000', NULL, 1),
(7664746, 1250186, 65234, '<td valign="top">I have a ton of that left over from the previous owner ... aside from that fact that it''s a bit of an obnoxious weed that keeps popping up in unwanted places, I''ve never looked at it this way. You saw a beauty I''ve totally missed. Now I''m going to have to go out there with my macro lens and see what I can see in person ;-)</td>', 'I have a ton of that left over from the previous owner ... aside from that fact that it''s a bit of an obnoxious weed that keeps popping up in unwanted places, I''ve never looked at it this way. You saw a beauty I''ve totally missed. Now I''m going to have to go out there with my macro lens and see what I can see in person ;-)', '2020-06-01 10:54:05.000000', NULL, 1),
(7664747, 1250119, 65234, '<td valign="top">I feel like those little hairs are going to prick me! Awesome macro.</td>', 'I feel like those little hairs are going to prick me! Awesome macro.', '2020-06-01 10:57:17.000000', NULL, 1),
(7664748, 1249635, 65234, '<td valign="top">I know how teensy those guys are; well done.</td>', 'I know how teensy those guys are; well done.', '2020-06-01 10:57:57.000000', NULL, 1),
(7664749, 1249921, 65234, '<td valign="top">Perfection.</td>', 'Perfection.', '2020-06-01 10:58:29.000000', NULL, 1),
(7664750, 1249250, 65234, '<td valign="top">Love, love, love that sun. Gorgeous image.</td>', 'Love, love, love that sun. Gorgeous image.', '2020-06-01 11:02:30.000000', NULL, 1),
(7664751, 1250298, 65234, '<td valign="top">Great moment to capture! Bird looks to me like it could use a little bit of sharpening.</td>', 'Great moment to capture! Bird looks to me like it could use a little bit of sharpening.', '2020-06-01 11:07:14.000000', NULL, 1),
(7664752, 1250333, 65234, '<td valign="top">They are simply adorable. Very nice capture and I love that one is looking right at me.</td>', 'They are simply adorable. Very nice capture and I love that one is looking right at me.', '2020-06-01 11:07:47.000000', NULL, 1),
(7664753, 1250187, 65234, '<td valign="top">Beautiful detail on this lovely bird. Nice diagonal on the composition and it''s looking at me, besides. Well done.</td>', 'Beautiful detail on this lovely bird. Nice diagonal on the composition and it''s looking at me, besides. Well done.', '2020-06-01 11:08:48.000000', NULL, 1),
(7664754, 1250091, 65234, '<td valign="top">Nice capture! Maybe could use a bit more detail in the dark areas, at least on my screen.</td>', 'Nice capture! Maybe could use a bit more detail in the dark areas, at least on my screen.', '2020-06-01 11:11:07.000000', NULL, 1),
(7664755, 1249913, 65234, '<td valign="top">Looks like he''s making a claim with that body language. Nice capture.</td>', 'Looks like he''s making a claim with that body language. Nice capture.', '2020-06-01 11:11:45.000000', NULL, 1),
(7664756, 1249475, 65234, '<td valign="top">Very pretty and well done; love the title.</td>', 'Very pretty and well done; love the title.', '2020-06-01 11:12:05.000000', NULL, 1),
(7664757, 1250266, 65234, '<td valign="top">Softly pretty. Looks very painterly.</td>', 'Softly pretty. Looks very painterly.', '2020-06-01 11:15:09.000000', NULL, 1),
(7664758, 1250104, 65234, '<td valign="top">Looks like Bee Balm, but not a varietal I''ve ever seen. Very nice DOF and detail.</td>', 'Looks like Bee Balm, but not a varietal I''ve ever seen. Very nice DOF and detail.', '2020-06-01 11:15:46.000000', NULL, 1),
(7664759, 1250343, 65234, '<td valign="top">This feels simple and yet there are branches everywhere. Maybe it''s the white background. Love the composition. This one just really appeals to me.</td>', 'This feels simple and yet there are branches everywhere. Maybe it''s the white background. Love the composition. This one just really appeals to me.', '2020-06-01 11:17:25.000000', NULL, 1),
(7664760, 1250323, 65234, '<td valign="top">Nice detail.</td>', 'Nice detail.', '2020-06-01 11:17:48.000000', NULL, 1),
(7664761, 1250338, 65234, '<td valign="top">Aww; very cute. I probably would have cropped a little tighter to show them off better.</td>', 'Aww; very cute. I probably would have cropped a little tighter to show them off better.', '2020-06-01 11:19:41.000000', NULL, 1),
(7664762, 1250255, 65234, '<td valign="top">The sunset adds interest to a scene I''m very familiar with.</td>', 'The sunset adds interest to a scene I''m very familiar with.', '2020-06-01 11:20:05.000000', NULL, 1),
