INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7665708, 1249934, 112739, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by willem:</b></div><hr/><i> Stunning image. Well prepared and executed with great clean and appealing result. I love the fact you still used depth of field in your image to create depth. Wow, 64 images from a 50 MP (?) Hasselblad. How long did that take to process? </i></td></tr></table> <br/> <br/>The processing is HeliconFocus took about 20 minutes, and then my regular masking and adjustments took another  couple days on and off. The HeliconFocus can work much faster with JPEG files, but I like to keep the raw information through the entire processing time.</td>', 'Originally posted by willem: Stunning image. Well prepared and executed with great clean and appealing result. I love the fact you still used depth of field in your image to create depth. Wow, 64 images from a 50 MP (?) Hasselblad. How long did that take to process?   The processing is HeliconFocus took about 20 minutes, and then my regular masking and adjustments took another  couple days on and off. The HeliconFocus can work much faster with JPEG files, but I like to keep the raw information through the entire processing time.', '2020-06-08 17:19:13.000000', NULL, 0),
